uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Audio Reactivity
uniform float u_bass;
uniform float u_mid;
uniform float u_treble;
uniform float u_vol;

// Mandatory Parameters
uniform float u_speed;
uniform float u_complexity;
uniform float u_glow_intensity;
uniform float u_color_shift;
uniform float u_alpha_fade;
uniform float u_brightness_fix;
uniform float u_zoom;
uniform float u_sharpness;
uniform float u_saturation; // New parameter for vibrancy
uniform float u_contrast;   // New parameter for depth

out vec4 fragColor;

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

// Color processing helpers
vec3 saturate(vec3 rgb, float adjustment) {
    const vec3 W = vec3(0.2125, 0.7154, 0.0721);
    vec3 intensity = vec3(dot(rgb, W));
    return mix(intensity, rgb, adjustment);
}

vec3 contrast(vec3 rgb, float adjustment) {
    return (rgb - 0.5) * adjustment + 0.5;
}

// Function to create smooth, organic wave shapes
float organicWave(vec2 uv, float offset) {
    float t = iTime * u_speed * 0.3 + offset;

    vec2 p = uv;
    p.x += sin(p.y * 2.0 + t) * 0.2;
    p.y += cos(p.x * 2.0 + t * 0.8) * 0.2;

    float wave = sin(p.x * 1.5 + t) * cos(p.y * 1.2 - t * 0.5);
    wave += sin(p.y * 3.0 + t * 1.2) * 0.2;

    float edgeWidth = mix(1.2, 0.05, u_sharpness);
    return smoothstep(-edgeWidth, edgeWidth, wave);
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    uv *= u_zoom;

    float t = iTime * u_speed * 0.2;
    uv *= 1.0 + 0.1 * sin(t * 0.5);
    uv = rot(sin(t * 0.2) * 0.1) * uv;

    // Enhanced Palette - Deepened base values to avoid "washout"
    vec3 colorA = vec3(0.01, 0.02, 0.06); // Deeper Space
    vec3 colorB = vec3(0.1, 0.4, 0.9);    // Vivid Electric Blue
    vec3 colorC = vec3(0.7, 0.2, 0.8);    // Rich Magenta/Violet
    vec3 colorD = vec3(1.0, 0.8, 0.4);    // Warm Golden Ember

    // Apply color shift uniform with more distinct transitions
    colorB = mix(colorB, vec3(0.0, 0.8, 0.6), u_color_shift);
    colorC = mix(colorC, vec3(0.9, 0.1, 0.2), u_color_shift);

    // Layer 1: Background Gradient
    vec3 finalColor = mix(colorA, colorB * 0.5, (uv.y / u_zoom) + 0.5);

    // Layer 2: Organic Flowing Waves
    float layers = clamp(u_complexity, 1.0, 10.0);
    for(float i = 0.0; i < 10.0; i++) {
        if(i >= layers) break;

        float flow = organicWave(uv * (1.0 + i * 0.2), i * 1.5);

        float lowEdge = mix(0.3, 0.48, u_sharpness);
        float highEdge = mix(0.7, 0.52, u_sharpness);
        float mask = smoothstep(lowEdge, highEdge, flow);

        // Dynamic layer coloring
        vec3 waveColor = mix(colorB, colorC, sin(i * 0.8 + t) * 0.5 + 0.5);
        // Inject bass reactivity into the colors directly for energy
        waveColor += colorD * (u_bass * 0.4); 

        float alphaFactor = mix(0.3, 0.7, u_sharpness);
        // Additive-style blend for punchier colors instead of flat mix
        finalColor += waveColor * mask * alphaFactor * (1.0 - i * 0.1) * 0.6;
    }

    // Layer 3: Central Glow
    float dist = length(uv);
    float pulse = (sin(t * 2.0) * 0.05 + 0.95) * (1.0 + u_mid * 0.2);
    float glowPower = mix(5.0, 12.0, u_sharpness);
    float glow = exp(-dist * (glowPower / (max(u_glow_intensity, 0.1) * pulse * u_zoom)));
    finalColor += colorD * glow * 0.5;

    // Layer 4: Floating Particles
    for(float i = 0.0; i < 12.0; i++) {
        float p_t = t + i * 123.456;
        vec2 p_pos = vec2(sin(p_t * 0.5) * 1.2, cos(p_t * 0.3) * 0.7) * u_zoom;
        float p_size = (0.005 + 0.01 * sin(p_t)) * u_zoom;
        float p_dist = length(uv - p_pos);
        float p_edge = mix(0.04, 0.002, u_sharpness) * u_zoom;
        finalColor += colorD * (smoothstep(p_size + p_edge, p_size, p_dist) * 0.4);
    }

    // --- Post Processing for "Nicer" Colors ---

    // Apply saturation to prevent the "grey" look
    finalColor = saturate(finalColor, u_saturation);

    // Apply contrast to give depth
    finalColor = contrast(finalColor, u_contrast);

    // Global Exposure
    finalColor *= u_brightness_fix;

    // Stronger Vignette for focus
    vec2 screenUV = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    float vignette = smoothstep(2.0, 0.4, length(screenUV));
    finalColor *= vignette;

    // Punchy Tone Mapping
    finalColor = pow(finalColor, vec3(1.1)); // Slight gamma curve for rich blacks
    finalColor = finalColor / (1.0 + finalColor * 0.2); // Soft clip

    float alpha = u_alpha_fade * vignette;
    fragColor = vec4(finalColor, alpha);
}
